template:
@php
    // 23 cards, six a page: what ->paginate(6) answers, made of a list rather than a query. Each
    // list reads a page parameter of its own; its links leave the others' out, or a crawler would
    // walk every combination of the three.
    $mode = in_array($pages ?? null, ['covered', 'shown', 'links'], true) ? $pages : 'covered';
    $name = $mode === 'covered' ? 'page' : ($mode === 'shown' ? 'more' : 'list');
    $all = collect(range(1, 23));
    $current = max(1, (int) request()->query($name, '1'));
    $list = new \Illuminate\Pagination\LengthAwarePaginator($all->forPage($current, 6)->values(), $all->count(), 6, $current, [
        'path' => request()->url(),
        'pageName' => $name,
    ]);
@endphp
<section class="b-showcase-more" data-wx-block="showcase-load-more" id="showcase-{{ $name }}">
    @if ($heading)
        <h2 class="b-showcase-more__heading">{{ $heading }}</h2>
    @endif
    @if ($note)
        <p class="b-showcase-more__note">{{ $note }}</p>
    @endif
    @if ($mode === 'links')
        <div class="b-showcase-more__grid">
            @foreach ($list as $number)
                <article class="b-showcase-more__card"><h3 class="b-showcase-more__title">Card {{ $number }}</h3><p class="b-showcase-more__text">Page {{ $list->currentPage() }} of {{ $list->lastPage() }}.</p></article>
            @endforeach
        </div>
        <x-webx-pagination :paginator="$list" class="b-showcase-more__pages" />
    @else
        <x-webx-load-more :paginator="$list" :pages="$mode">
            <div class="b-showcase-more__grid" data-webx-load-more-list>
                @foreach ($list as $number)
                    <article class="b-showcase-more__card"><h3 class="b-showcase-more__title">Card {{ $number }}</h3><p class="b-showcase-more__text">Page {{ $list->currentPage() }} of {{ $list->lastPage() }}.</p></article>
                @endforeach
            </div>
        </x-webx-load-more>
    @endif
</section>

styles:
.b-showcase-more {
    max-width: var(--site-container-width);
    margin: 0 auto;
    padding: var(--site-space-6) var(--site-gutter);
}

.b-showcase-more__heading {
    margin: 0 0 var(--site-space-2);
    font-size: var(--site-font-size-3);
}

.b-showcase-more__note {
    margin: 0 0 var(--site-space-4);
    color: var(--site-color-text-muted);
}

.b-showcase-more__grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(min(100%, 14rem), 1fr));
    gap: var(--site-space-4);
}

.b-showcase-more__card {
    padding: var(--site-space-4);
    border: 1px solid var(--site-color-border);
    border-radius: var(--site-radius-md);
    background: var(--site-color-surface);
}

.b-showcase-more__title {
    margin: 0 0 var(--site-space-1);
    font-size: var(--site-font-size-5);
}

.b-showcase-more__text {
    margin: 0;
    color: var(--site-color-text-muted);
}

.b-showcase-more__pages {
    margin-top: var(--site-space-5);
}
